#!/usr/bin/env python3
"""Atheris fuzz harness — crc_main surface: crc(data: bytes) entrypoint."""
import atheris
import sys
import os

# Add src to path for direct import
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "../../../../../../src"))

from crc10_gsm import crc


def test_one_input(data: bytes) -> None:
    """Feed fuzzer-generated bytes into crc() and check invariants."""
    result = crc(data)
    # 1. Result must be an int
    assert isinstance(result, int), f"crc() returned non-int: {type(result)}"
    # 2. Result must be in [0, 1024) — 10-bit mask
    assert 0 <= result < 1024, f"crc() out of range: {result}"
    # 3. crc of empty bytes must be 0x3FF (XOROUT applied to init=0)
    if len(data) == 0:
        assert result == 0x3FF, f"crc(b'') = 0x{result:03X}, expected 0x3FF"


def main() -> None:
    atheris.Setup(sys.argv, test_one_input)
    atheris.Fuzz()


if __name__ == "__main__":
    main()
